let page='home',group='All',subject='All',grade=9,unitIndex=0,activeSubject=null,activeUnit='',quizAnswers=[],quizChecked=false,bankPage=0,bankGrade='all',bankResponses={},bankSubmitted=false;
const allowedSubjects=['Mathematics','English','SAT','Biology','Chemistry','Physics','Geography','Economics','History'];
